INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('c4566c85-797e-499d-ae19-11db3cea8862', 'f0f35259-85b3-44fa-99c1-4f9ec87c9f4d', 4, 'Desapego do passado', NULL, '{"intro": "Tentar viver no passado \u00e9 tentar preencher um vaso quebrado com areia.", "prayer": "Queime esse papel simbolicamente ou rasgue-o.", "practice": "Liste tr\u00eas coisas que te mant\u00eam preso ao que j\u00e1 passou.", "reflection": "O passado \u00e9 um espelho, n\u00e3o uma morada.", "journal_prompt": "Quem voc\u00ea seria se n\u00e3o carregasse esse passado?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;